function buildGraph(n, edges) {
  const adj = Array.from({ length: n }, () => []);   // one empty list per vertex
  for (const [u, v] of edges) {
    adj[u].push(v);           // u lists v as a neighbour...
    adj[v].push(u);           // ...and v lists u (leave this out for a directed graph)
  }
  return adj;
}

def build_graph(n, edges):
    adj = [[] for _ in range(n)]      # one empty list per vertex
    for u, v in edges:
        adj[u].append(v)              # u lists v as a neighbour...
        adj[v].append(u)              # ...and v lists u (leave this out for a directed graph)
    return adj

List<List<Integer>> buildGraph(int n, int[][] edges) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());   // one empty list per vertex
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);      // u lists v as a neighbour...
        adj.get(e[1]).add(e[0]);      // ...and v lists u (leave this out for a directed graph)
    }
    return adj;
}

vector<vector<int>> buildGraph(int n, vector<vector<int>>& edges) {
    vector<vector<int>> adj(n);                 // one empty list per vertex
    for (auto& e : edges) {
        adj[e[0]].push_back(e[1]);    // u lists v as a neighbour...
        adj[e[1]].push_back(e[0]);    // ...and v lists u (leave this out for a directed graph)
    }
    return adj;
}

function buildMatrix(n, edges) {
  const matrix = Array.from({ length: n }, () => new Array(n).fill(0));
  for (const [u, v] of edges) {
    matrix[u][v] = 1;         // 1 means "u and v are joined"
    matrix[v][u] = 1;         // both ways for an undirected graph
  }
  return matrix;
}

def build_matrix(n, edges):
    matrix = [[0] * n for _ in range(n)]
    for u, v in edges:
        matrix[u][v] = 1              # 1 means "u and v are joined"
        matrix[v][u] = 1              # both ways for an undirected graph
    return matrix

int[][] buildMatrix(int n, int[][] edges) {
    int[][] matrix = new int[n][n];
    for (int[] e : edges) {
        matrix[e[0]][e[1]] = 1;       // 1 means "u and v are joined"
        matrix[e[1]][e[0]] = 1;       // both ways for an undirected graph
    }
    return matrix;
}

