const DIRS = [[-1, 0], [1, 0], [0, -1], [0, 1]];   // up, down, left, right

function neighbours(rows, cols, r, c) {
  const out = [];
  for (const [dr, dc] of DIRS) {
    const nr = r + dr, nc = c + dc;
    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) out.push([nr, nc]);   // stay inside the grid
  }
  return out;
}

static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};   // up, down, left, right

List<int[]> neighbours(int rows, int cols, int r, int c) {
    List<int[]> out = new ArrayList<>();
    for (int[] d : DIRS) {
        int nr = r + d[0], nc = c + d[1];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) out.add(new int[]{nr, nc});   // stay inside
    }
    return out;
}

const int DIRS[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};       // up, down, left, right

vector<vector<int>> neighbours(int rows, int cols, int r, int c) {
    vector<vector<int>> out;
    for (auto& d : DIRS) {
        int nr = r + d[0], nc = c + d[1];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) out.push_back({nr, nc});   // stay inside
    }
    return out;
}
